import{_ as t,o as e,c as d,a3 as p}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"种植与自动收割机机制研究与应用","description":"","frontmatter":{"translationSource":{"title":"种植与自动收割机机制研究与应用","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=atfxNNyQUUJH68TDGeR9Vl","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/planting-and-automatic-harvester-mechanics-research-and-applications"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/planting-and-automatic-harvester-mechanics-research-and-applications"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/planting-and-automatic-harvester-mechanics-research-and-applications"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/planting-and-automatic-harvester-mechanics-research-and-applications"}]]},"headers":[],"relativePath":"zh/planting-and-automatic-harvester-mechanics-research-and-applications.md","filePath":"zh/page-atfxNNyQUUJH68TDGeR9Vl.md"}'),r={name:"zh/planting-and-automatic-harvester-mechanics-research-and-applications.md"};function s(i,a,o,l,n,c){return e(),d("div",null,[...a[0]||(a[0]=[p('<div class="logistics-content"><h1 id="种植与自动收割机机制研究与应用" tabindex="-1">种植与自动收割机机制研究与应用 <a class="header-anchor" href="#种植与自动收割机机制研究与应用" aria-label="Permalink to &quot;种植与自动收割机机制研究与应用&quot;">​</a></h1><blockquote><p>源页面 ID：<code>atfxNNyQUUJH68TDGeR9Vl</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=atfxNNyQUUJH68TDGeR9Vl" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>谁开的页面：ko鸟</p><p>贡献者：ko鸟、jnk、（谁写的记得留名啊）</p><p>最后更新：2026-10-24</p><p>注意，内容可能随版本更新。本页面或可提升至缘缘庄小助手子页面之外。</p><p><span id="source-block-1EM2GjaCSjUNevMZLWaYrj"></span></p><h2 id="田地的机制" tabindex="-1">田地的机制 <a class="header-anchor" href="#田地的机制" aria-label="Permalink to &quot;田地的机制&quot;">​</a></h2><p><span id="source-block-iPYraacA0L1rll8TWggsvk"></span></p><h3 id="地块生长周期" tabindex="-1">地块生长周期 <a class="header-anchor" href="#地块生长周期" aria-label="Permalink to &quot;地块生长周期&quot;">​</a></h3><p>生长周期由多个阶段构成，部分阶段需要玩家或设备进行交互操作（如育苗、浇水），部分阶段需要等待作物生长。</p><p>游戏内点击地块即可查看该作物的生长周期。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5c392cde2dba0456.q90-74df595a6ca55216.webp" alt="种植与自动收割机机制研究与应用"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e972e4587eb7c624.q90-bc132a54bddbcf22.webp" alt="种植与自动收割机机制研究与应用"></p><p>作物生长周期列表：</p><ul><li><p>荞花、柑实：</p></li><li><p>芽针、锦草</p></li><li><p>灰芦麦、苦叶椒</p></li><li><p>金石稻、琼叶参</p></li><li><p>平薯、球豆、茄果、脆蔗、油菜、白瓜</p></li><li><p>多味菇、青菜、青叶莓</p></li></ul><p><span id="source-block-Wdc2VvTg4d9uvdJi2pwh7S"></span></p><h3 id="成熟时间与产出" tabindex="-1">成熟时间与产出 <a class="header-anchor" href="#成熟时间与产出" aria-label="Permalink to &quot;成熟时间与产出&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>成熟时间<br>只计生长阶段</th><th>需求</th><th>主产出<br>基础产量</th><th>副产出<br>基础产量</th></tr></thead><tbody><tr><td>荞花、柑实</td><td></td><td>浇水</td><td>10作物</td><td>1-3优质作物</td></tr><tr><td>芽针、锦草</td><td>1小时</td><td>2次浇水</td><td>10作物</td><td>1-3优质作物</td></tr><tr><td>灰芦麦、苦叶椒</td><td>12小时</td><td>浇水</td><td>30作物</td><td></td></tr><tr><td>金石稻、琼叶参</td><td>12小时</td><td>3次浇水</td><td>30作物</td><td></td></tr><tr><td>以上作物放置无限制，以下作物田块仅能放置于祀的画</td><td></td><td></td><td></td><td></td></tr><tr><td>平薯、球豆</td><td>8小时</td><td>浇水</td><td>30作物</td><td></td></tr><tr><td>茄果、脆蔗、油菜、白瓜</td><td>8小时</td><td>浇水</td><td>30作物</td><td></td></tr><tr><td>多味菇、青菜、青叶莓（非变异版）</td><td>8小时</td><td>浇水</td><td>30作物</td><td></td></tr><tr><td>多味菇、青菜、青叶莓（变异版）</td><td>8小时</td><td>在非变异版的基础上息壤气环境30s</td><td>30作物</td><td>30变异作物</td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><span id="source-block-IV3hvhDZTnbS1fqEpawiIx"></span></p><h3 id="浇水方式以及消耗" tabindex="-1">浇水方式以及消耗 <a class="header-anchor" href="#浇水方式以及消耗" aria-label="Permalink to &quot;浇水方式以及消耗&quot;">​</a></h3><p><span id="source-block-IIhvOBmohhOcx7qBPq5stH"></span></p><h4 id="浇水机" tabindex="-1">浇水机 <a class="header-anchor" href="#浇水机" aria-label="Permalink to &quot;浇水机&quot;">​</a></h4><p>目前所有地块的浇水阶段都需要洒水机供应30单位的水量，一台洒水机给多个地块浇水时，会按照相同的速度推进所有地块的浇水进度，不会由于地块数量的增加而消耗额外的水量。多个洒水机为同一田块浇水时，会叠加速度，总浇水量不变。</p><p>由于浇水机在范围中田块进入浇水阶段时，自动开始浇水的特性，浇水机也可以用于检测田块的状态。</p><p><span id="source-block-ILlc7DlSxgouw8GOYWkRso"></span></p><h4 id="气体散布机" tabindex="-1">气体散布机 <a class="header-anchor" href="#气体散布机" aria-label="Permalink to &quot;气体散布机&quot;">​</a></h4><p>可以向气体散布机通入水蒸气，形成湿润环境，处于湿润环境内，并处于浇水阶段的田块会自动推进浇水进度。由于形成湿润环境所需要的消耗是固定的，显然不会由于地块数量的增加而消耗额外的水汽量。</p><p>在限速6的条件下，通入4个水蒸气即可完成田块的浇水阶段。实测发现通入3个水蒸气会刚好差最后一丁点儿进度，可能与散布机没有连续运作有关。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0e8510f12f21e4d6.q90-90df22ac67c30690.webp" alt="种植与自动收割机机制研究与应用"></p><p><span id="source-block-EkwbvKCZKxA1Z86uAFjeqG"></span></p><h3 id="变异与相邻增产" tabindex="-1">变异与相邻增产 <a class="header-anchor" href="#变异与相邻增产" aria-label="Permalink to &quot;变异与相邻增产&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-14e1ddb91f3a6632.q90-a004668fedaa1af9.webp" alt="种植与自动收割机机制研究与应用"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c6bfd46b6dcc69eb.q90-c56e1cc439e812a4.webp" alt="种植与自动收割机机制研究与应用"></p><p>在浇过水的非变异版的基础上，施加可不连续的30s的息壤环境后（之后采收前不需要继续施加），会继承生长时长变成变异版植物田块，变异后会进行30s相邻增产过程。</p><p>相邻增产在田块邻接有同类植物时，每一块植物田会使得其增产20%(加算)，无论邻接田块是否已经变异。</p><p>相邻增产的效果实际上在收获时结算，而不是在相邻增产过程中结算，即过了30s后，再改动布局，会导致增产效果变动。</p><p>采收后或者回收变回普通田块。</p><p><span id="source-block-9wJKZMeO4XEBGfQwgjyxwS"></span></p><h3 id="肥料机制" tabindex="-1">肥料机制 <a class="header-anchor" href="#肥料机制" aria-label="Permalink to &quot;肥料机制&quot;">​</a></h3><p>肥料增产与相邻增产加算</p><p><span id="source-block-8PqQsBoHitKAo26fgJLofp"></span></p><h2 id="收割机基本规律" tabindex="-1">收割机基本规律 <a class="header-anchor" href="#收割机基本规律" aria-label="Permalink to &quot;收割机基本规律&quot;">​</a></h2><p><span id="source-block-CHWrkPO22DCEc4i1bEGG2s"></span></p><h3 id="收割时机" tabindex="-1">收割时机 <a class="header-anchor" href="#收割时机" aria-label="Permalink to &quot;收割时机&quot;">​</a></h3><p>基本可以认为随时检查有无成熟地块，如果成熟，且能够塞进储存格（即使只有部分能塞，见后）就收割。离线情况不清楚。</p><p>如果能收割，就把收获产物放进储存格中（溢出自动销毁，见后），然后自动完成回到育苗阶段田块的育苗操作。如果配合水蒸气散布或者洒水机，就可以在完成浇水后直接让田块进入生长阶段。</p><p><span id="source-block-d9eu8EqE2npBGUd2aqLVEq"></span></p><h3 id="收割顺序" tabindex="-1">收割顺序 <a class="header-anchor" href="#收割顺序" aria-label="Permalink to &quot;收割顺序&quot;">​</a></h3><p>目前已有证据可排除：按位置顺序收割，按成熟时间收割，按放置顺序收割</p><p>现在完全搞不明白是按什么顺序。。</p><p><span id="source-block-XbsbxMYQVCSxxsYgX0L8lN"></span></p><h3 id="收割时产物溢出的判断" tabindex="-1">收割时产物溢出的判断 <a class="header-anchor" href="#收割时产物溢出的判断" aria-label="Permalink to &quot;收割时产物溢出的判断&quot;">​</a></h3><p><strong>对于单产出作物，诸如白瓜，甘蔗</strong></p><p><span class="mark-purple"><u>a. 当收割机该作物有储存格未满，但没有其他格子能继续放该作物时，偷吃超出该格50上限的部分。</u></span></p><p>举例：有一格30白瓜，其他格子都是其他作物或者装满50白瓜，再收一块白瓜地，这一格变50，多余的10直接无了</p><p><strong>对于平薯、豆角非变异有副产出作物</strong></p><p>主副产出任一有空位都会触发收割，并且也同样适用规则a</p><p><span class="mark-purple"><u>b.只剩最后一个储存格时，会储存主产物，偷吃副产物</u></span></p><p>举例：只剩一个格子，收一块土豆地，30土豆进储存，3土豆叶子直接无了。再收一块，20进储存，10土豆和3叶子直接无了</p><p><span class="mark-purple"><u>c.副产物未满，主产物满时，会直接偷吃全部主产物</u></span></p><p>举例：只剩两个格子，收一块土豆地，30土豆3叶子进储存，再收，20土豆3叶子进储存，10土豆无了；还有土豆地会继续收，3叶子进储存，50土豆直接无了。这种情况最多能偷吃你450个土豆</p><p><a href="https://www.bilibili.com/video/BV1PLJ86VEnr" target="_blank" rel="noreferrer">【终末地】以防你不知道自动收割机会偷吃土豆</a></p><blockquote><p>不是吧，怎么1.6了又有偷吃的猪？</p></blockquote><p>因为土豆叶子出的很少，所以土豆满了土豆叶子没满的话也不会停止收割，一直收土豆，然后收不进来的土豆全被偷吃了！气死我了！<br> 估计豌豆也是</p><p><strong>对于变异作物，如变异青菜</strong></p><p>变异田地同时产出相同数量的变异和非变异版本</p><p>如果把非变异版本视为主产物，变异版本视为副产物（虽然有点奇怪），同样适用以上规则a-c</p><p>注意，由于优先储存非变异版本，所以在只剩1格时会出现非变异版本把变异版本卡掉的情况。</p><hr><p><span id="source-block-BSLjmbYaB0yYBBzfnHhX7E"></span></p><h2 id="应用方案" tabindex="-1">应用方案 <a class="header-anchor" href="#应用方案" aria-label="Permalink to &quot;应用方案&quot;">​</a></h2><p><span id="source-block-mGNGNOSKycEqigA1nGal5C"></span></p><h3 id="方案名" tabindex="-1">方案名 <a class="header-anchor" href="#方案名" aria-label="Permalink to &quot;方案名&quot;">​</a></h3><p>解决什么问题：</p><p>布局：</p><p>君老大的想法：第一块检测田被收割→检测到第一块田浇水→开启其他田的水蒸气浇水浇水→给第二块检测田浇水→第二块检测田被收割→检测到第二块田浇水→开启其他田的水蒸气浇水→给第一块检测田浇水</p><p>目的是让检测田最后收割</p><p><span id="source-block-FrtI9vYcnh1hT51KUWajaY"></span></p><h3 id="方案名-1" tabindex="-1">方案名 <a class="header-anchor" href="#方案名-1" aria-label="Permalink to &quot;方案名&quot;">​</a></h3><p>解决什么问题：</p><p>布局：</p></div>',1)])])}const u=t(r,[["render",s]]);export{b as __pageData,u as default};
